'use client';

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useRouter } from 'next/navigation';
import { Navbar } from '@/components/layout/Navbar';
import { Button } from '@/components/ui/Button';
import { roomTemplates } from '@/lib/templates';
import { useDesignStore } from '@/lib/store';
import { X, Eye, ArrowRight, MapPin } from 'lucide-react';
import type { RoomTemplate } from '@/lib/types';

export default function TemplatesPage() {
  const router = useRouter();
  const { createDesign } = useDesignStore();
  const [selectedTemplate, setSelectedTemplate] = useState<RoomTemplate | null>(null);

  const handleStartDesign = (templateId: string) => {
    console.log('[DEBUG] handleStartDesign called with:', templateId);
    try {
      const success = createDesign(templateId as any);
      console.log('[DEBUG] createDesign returned:', success);
      if (success) {
        console.log('[DEBUG] Navigating to /studio');
        router.push('/studio');
      } else {
        console.error('[DEBUG] createDesign returned false for template:', templateId);
        alert('Failed to load template. Please try again.');
      }
    } catch (err) {
      console.error('[DEBUG] Error in handleStartDesign:', err);
      alert('Error: ' + (err as Error).message);
    }
  };

  const getTemplateTag = (id: string) => {
    if (['banquet', 'wedding', 'lounge', 'small-event'].includes(id)) return 'Indoor';
    return 'Outdoor';
  };

  const getTemplateStyle = (id: string) => {
    if (id === 'wedding') return 'Elegant';
    if (id === 'lounge') return 'Modern';
    if (id === 'banquet') return 'Formal';
    return 'Casual';
  };

  return (
    <div className="min-h-screen bg-[#F7F7F5]">
      <Navbar />
      
      {/* Header */}
      <section className="pt-32 pb-12 px-4 sm:px-6 lg:px-8">
        <div className="max-w-7xl mx-auto text-center">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
          >
            <h1 className="text-4xl lg:text-5xl font-bold text-[#111111] mb-4">
              Choose Your Venue
            </h1>
            <p className="text-lg text-[#5A5A5F] max-w-2xl mx-auto">
              Select a template to start designing. Each venue offers unique customization options for your perfect event.
            </p>
          </motion.div>
        </div>
      </section>

      {/* Templates Grid */}
      <section className="pb-24 px-4 sm:px-6 lg:px-8">
        <div className="max-w-7xl mx-auto">
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-6 lg:gap-8">
            {roomTemplates.map((template, i) => (
              <motion.div
                key={template.id}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.1 }}
                className="group"
              >
                {/* Card */}
                <div className="bg-white rounded-2xl overflow-hidden shadow-md border border-[#E5E5E8] hover:shadow-xl transition-all duration-300">
                  {/* Image Area */}
                  <div className="relative aspect-[4/3] overflow-hidden">
                    <div 
                      className="absolute inset-0 transition-transform duration-500 group-hover:scale-105"
                      style={{ 
                        background: `linear-gradient(135deg, ${template.defaultSettings.wallColor} 0%, ${template.defaultSettings.floorColor} 100%)` 
                      }}
                    />
                    
                    {/* Overlay */}
                    <div className="absolute inset-0 bg-gradient-to-t from-black/50 via-transparent to-transparent" />
                    
                    {/* Tags */}
                    <div className="absolute top-4 left-4 flex gap-2">
                      <span className="px-3 py-1 bg-white/90 backdrop-blur-sm rounded-full text-xs font-medium text-[#111111]">
                        {getTemplateTag(template.id)}
                      </span>
                      <span className="px-3 py-1 bg-[#C6A85C]/90 backdrop-blur-sm rounded-full text-xs font-medium text-[#111111]">
                        {getTemplateStyle(template.id)}
                      </span>
                    </div>
                    
                    {/* Preview Button */}
                    <button
                      onClick={() => setSelectedTemplate(template)}
                      className="absolute top-4 right-4 w-10 h-10 bg-white/90 backdrop-blur-sm rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300 hover:bg-white"
                    >
                      <Eye className="w-5 h-5 text-[#111111]" />
                    </button>
                    
                    {/* Title Overlay */}
                    <div className="absolute bottom-0 left-0 right-0 p-6">
                      <h3 className="text-2xl font-bold text-white mb-1">{template.name}</h3>
                      <div className="flex items-center gap-1 text-white/80 text-sm">
                        <MapPin className="w-4 h-4" />
                        <span className="capitalize">{template.defaultSettings.lightingPreset} ambiance</span>
                      </div>
                    </div>
                  </div>
                  
                  {/* Content */}
                  <div className="p-6">
                    <p className="text-[#5A5A5F] mb-6 line-clamp-2">{template.description}</p>
                    
                    <div className="flex gap-3">
                      <Button 
                        onClick={() => handleStartDesign(template.id)}
                        className="flex-1"
                        size="md"
                        type="button"
                      >
                        Use Template
                      </Button>
                      <Button 
                        variant="outline"
                        size="md"
                        onClick={() => setSelectedTemplate(template)}
                        className="px-4"
                      >
                        <Eye className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* Preview Modal */}
      <AnimatePresence>
        {selectedTemplate && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm"
            onClick={() => setSelectedTemplate(null)}
          >
            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 20 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 20 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white rounded-3xl max-w-2xl w-full max-h-[90vh] overflow-hidden shadow-2xl"
            >
              {/* Header Image */}
              <div 
                className="relative h-64 sm:h-80"
                style={{ 
                  background: `linear-gradient(135deg, ${selectedTemplate.defaultSettings.wallColor} 0%, ${selectedTemplate.defaultSettings.floorColor} 100%)` 
                }}
              >
                <button
                  onClick={() => setSelectedTemplate(null)}
                  className="absolute top-4 right-4 w-10 h-10 bg-white/90 backdrop-blur-sm rounded-full flex items-center justify-center hover:bg-white transition-colors"
                >
                  <X className="w-5 h-5 text-[#111111]" />
                </button>
                
                <div className="absolute bottom-0 left-0 right-0 p-8 bg-gradient-to-t from-black/60 to-transparent">
                  <span className="inline-block px-3 py-1 bg-[#C6A85C] rounded-full text-xs font-medium text-[#111111] mb-3">
                    {getTemplateStyle(selectedTemplate.id)}
                  </span>
                  <h2 className="text-3xl sm:text-4xl font-bold text-white">{selectedTemplate.name}</h2>
                </div>
              </div>

              {/* Content */}
              <div className="p-6 sm:p-8">
                <p className="text-[#5A5A5F] text-lg mb-8">{selectedTemplate.description}</p>

                {/* Details Grid */}
                <div className="grid grid-cols-2 gap-4 mb-8">
                  <div className="bg-[#F7F7F5] rounded-xl p-4">
                    <p className="text-sm text-[#8C8C92] mb-1">Lighting</p>
                    <p className="text-[#111111] font-medium capitalize">{selectedTemplate.defaultSettings.lightingPreset}</p>
                  </div>
                  <div className="bg-[#F7F7F5] rounded-xl p-4">
                    <p className="text-sm text-[#8C8C92] mb-1">Flooring</p>
                    <p className="text-[#111111] font-medium capitalize">{selectedTemplate.defaultSettings.floorMaterial}</p>
                  </div>
                  <div className="bg-[#F7F7F5] rounded-xl p-4">
                    <p className="text-sm text-[#8C8C92] mb-1">Backdrop</p>
                    <p className="text-[#111111] font-medium capitalize">{selectedTemplate.defaultSettings.backdropStyle}</p>
                  </div>
                  <div className="bg-[#F7F7F5] rounded-xl p-4">
                    <p className="text-sm text-[#8C8C92] mb-1">Type</p>
                    <p className="text-[#111111] font-medium">{getTemplateTag(selectedTemplate.id)}</p>
                  </div>
                </div>

                {/* Actions */}
                <div className="flex gap-4">
                  <Button 
                    onClick={() => {
                      const success = createDesign(selectedTemplate.id as any);
                      if (success) {
                        setSelectedTemplate(null);
                        router.push('/studio');
                      } else {
                        console.error('Failed to create design for template:', selectedTemplate.id);
                        alert('Failed to load template. Please try again.');
                      }
                    }}
                    className="flex-1"
                    size="lg"
                    type="button"
                  >
                    Start Designing
                    <ArrowRight className="w-4 h-4 ml-2" />
                  </Button>
                  <Button 
                    variant="outline"
                    onClick={() => setSelectedTemplate(null)}
                    size="lg"
                    type="button"
                  >
                    Close
                  </Button>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
